"""
Lesson 25 - Gaussian Mixture Models fitted with the EM algorithm (from scratch)

Problem story: an online shop has 2 numbers per customer (average basket value, visits per month).  There are hidden groups -
bargain hunters, regulars, big spenders - but they overlap, and nobody wrote down who belongs where.  A Gaussian mixture says:
"every customer was generated by first picking a group (with probability pi_k), then drawing from that group's Gaussian".
EM alternates: guess how responsible each group is for each customer (E-step), then refit each group to the customers it is
responsible for (M-step).

Implemented: GMM with full / diagonal / spherical covariances, log-sum-exp stable E-step, closed-form M-step, k-means++ start,
log-likelihood tracking (checked to be monotone), BIC / AIC, a small k-means for the hard-vs-soft comparison.

Outputs: gmm_em.gif (EM iterations), gmm_model_selection.gif (K = 1..7 with BIC/AIC and uncertainty map)
Run:  python gmm_em.py
"""
import sys, pathlib, itertools

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[2]))
from common.utils import *  # noqa: F401,F403
from matplotlib.patches import Ellipse
import matplotlib


def logsumexp(a, axis=1):
    m = a.max(axis, keepdims=True)
    return (m + np.log(np.exp(a - m).sum(axis, keepdims=True))).squeeze(axis)


class GMM:
    def __init__(self, K=3, cov_type="full", n_iters=100, tol=1e-7, reg=1e-6, seed=0):
        self.K, self.cov_type, self.n_iters, self.tol, self.reg, self.seed = K, cov_type, n_iters, tol, reg, seed

    # ---- Gaussian log-density for every (point, component):  log N(x | mu_k, S_k)
    def _log_prob(self, X):
        n, d = X.shape
        out = np.empty((n, self.K))
        for k in range(self.K):
            L = np.linalg.cholesky(self.cov[k])
            z = np.linalg.solve(L, (X - self.mu[k]).T)                       # whitened residuals
            out[:, k] = -0.5 * (d * np.log(2 * np.pi) + 2 * np.log(np.diag(L)).sum() + (z ** 2).sum(0))
        return out

    def e_step(self, X):
        """responsibilities r_ik = pi_k N(x_i|k) / sum_j pi_j N(x_i|j), computed in log space; also returns the log-likelihood."""
        lp = self._log_prob(X) + np.log(self.pi)
        ll = logsumexp(lp)
        return np.exp(lp - ll[:, None]), float(ll.sum())

    def m_step(self, X, R):
        n, d = X.shape
        Nk = R.sum(0) + 1e-12                                             # "effective number of points" of each component
        self.pi = Nk / n
        self.mu = (R.T @ X) / Nk[:, None]
        cov = []
        for k in range(self.K):
            D = X - self.mu[k]
            S = (R[:, k, None] * D).T @ D / Nk[k]
            if self.cov_type == "diag":
                S = np.diag(np.diag(S))
            elif self.cov_type == "spherical":
                S = np.eye(d) * np.trace(S) / d
            cov.append(S + self.reg * np.eye(d))                          # tiny ridge keeps S positive definite (avoids singularities)
        self.cov = np.array(cov)

    def init(self, X):
        r = np.random.default_rng(self.seed)
        n = len(X)
        centers = [X[r.integers(n)]]
        for _ in range(self.K - 1):                                       # k-means++ seeding
            d2 = np.min([np.sum((X - c) ** 2, 1) for c in centers], 0)
            centers.append(X[r.choice(n, p=d2 / d2.sum())])
        self.mu = np.array(centers)
        self.cov = np.array([np.cov(X.T) * 0.6 for _ in range(self.K)])
        self.pi = np.full(self.K, 1 / self.K)

    def fit(self, X, record=False):
        X = np.asarray(X, float)
        self.init(X)
        self.history, self.ll = [], []
        prev = -np.inf
        for it in range(self.n_iters + 1):
            R, ll = self.e_step(X)
            self.ll.append(ll)
            if record:
                self.history.append(dict(mu=self.mu.copy(), cov=self.cov.copy(), pi=self.pi.copy(), R=R.copy(), ll=ll))
            if abs(ll - prev) < self.tol * max(1.0, abs(ll)):
                break
            prev = ll
            self.m_step(X, R)
        self.n_iter_ = len(self.ll) - 1
        return self

    def predict_proba(self, X):
        return self.e_step(np.asarray(X, float))[0]

    def predict(self, X):
        return self.predict_proba(X).argmax(1)

    def score(self, X):
        return self.e_step(np.asarray(X, float))[1]

    def n_params(self, d):
        per = {"full": d * (d + 1) / 2, "diag": d, "spherical": 1}[self.cov_type]
        return self.K * d + self.K * per + (self.K - 1)

    def bic(self, X):
        return -2 * self.score(X) + self.n_params(X.shape[1]) * np.log(len(X))

    def aic(self, X):
        return -2 * self.score(X) + 2 * self.n_params(X.shape[1])


def best_of(X, K, cov_type="full", n_init=4):
    fits = [GMM(K, cov_type, seed=s).fit(X) for s in range(n_init)]
    return max(fits, key=lambda g: g.score(X))


def kmeans(X, K, iters=50, seed=0):
    r = np.random.default_rng(seed)
    C = X[r.choice(len(X), K, replace=False)]
    for _ in range(iters):
        lab = np.argmin(((X[:, None] - C[None]) ** 2).sum(2), 1)
        C = np.array([X[lab == k].mean(0) if np.any(lab == k) else C[k] for k in range(K)])
    return lab, C


def shop_data(n=450, seed=4):
    r = rng_(seed)
    pi = np.array([0.4, 0.4, 0.2])
    mus = np.array([[-2.0, -0.6], [1.6, 0.0], [0.0, 2.6]])
    covs = np.array([[[1.4, 0.9], [0.9, 0.7]], [[0.5, -0.1], [-0.1, 1.8]], [[1.2, 0.0], [0.0, 0.25]]])
    z = r.choice(3, n, p=pi)
    X = np.array([r.multivariate_normal(mus[k], covs[k]) for k in z])
    return X, z


def match_accuracy(z, lab, K):
    return max(np.mean(np.array(p)[lab] == z) for p in itertools.permutations(range(K)))


def draw_ellipses(ax, mu, cov, pi=None, colors=CAT, lw=1.8):
    for k in range(len(mu)):
        ev, V = np.linalg.eigh(cov[k])
        ang = np.degrees(np.arctan2(V[1, 1], V[0, 1]))
        for s, a in ((1, 1.0), (2, 0.5)):
            ax.add_patch(Ellipse(mu[k], 2 * s * np.sqrt(ev[1]), 2 * s * np.sqrt(ev[0]), angle=ang, fill=False, edgecolor=colors[k], linewidth=lw, alpha=a, zorder=5))
        ax.scatter(*mu[k], marker="X", s=110, color=colors[k], edgecolor=INK, zorder=6)


def blend(R, K):
    cols = np.array([matplotlib.colors.to_rgb(CAT[k]) for k in range(K)])
    return np.clip(R @ cols, 0, 1)


def em_gif():
    X, z = shop_data()
    g = GMM(3, seed=1).fit(X, record=True)
    ll = np.array(g.ll)
    assert np.all(np.diff(ll) > -1e-8), "EM must never decrease the likelihood"
    print(f"  EM converged in {g.n_iter_} iterations; log-likelihood {ll[0]:.1f} -> {ll[-1]:.1f} (monotone: min step {np.diff(ll).min():+.2e});  weights {np.round(g.pi, 3)} (true 0.4/0.4/0.2)")
    hard_lab, _ = kmeans(X, 3)
    print(f"  cluster accuracy vs hidden groups: GMM (soft, full cov) {match_accuracy(z, g.predict(X), 3):.3f}  k-means (hard, spherical) {match_accuracy(z, hard_lab, 3):.3f}")
    star = int(np.argsort(np.linalg.norm(X - [-0.3, 0.9], axis=1))[0])                       # a customer between groups
    frames = sorted(set(np.unique(np.round(np.geomspace(1, len(g.history), 22)).astype(int) - 1).tolist() + [0, len(g.history) - 1]))
    fig, (a1, a2, a3) = new_fig(1, 3, figsize=(13, 4.8), title="EM for a Gaussian mixture: soft-assign the customers, refit the groups, repeat")
    fig.subplots_adjust(left=0.05, right=0.985, bottom=0.2, top=0.84, wspace=0.28)
    with Animator(here(__file__, "gmm_em.gif"), fps=4, hold=3.5) as anim:
        for i in frames:
            h = g.history[i]
            a1.clear()
            a1.scatter(X[:, 0], X[:, 1], s=16, c=blend(h["R"], 3), edgecolor=INK, linewidth=0.2, zorder=3)
            draw_ellipses(a1, h["mu"], h["cov"])
            a1.scatter(*X[star], marker="*", s=230, color="white", edgecolor=INK, linewidth=1.2, zorder=8)
            a1.set(title="Soft assignments + Gaussians", xlabel="average basket value", ylabel="visits per month", xlim=(-6, 5), ylim=(-3.5, 5))
            a2.clear()
            a2.plot(range(i + 1), ll[: i + 1], color=BLUE)
            a2.scatter([i], [ll[i]], color=ORANGE, zorder=5, edgecolor=INK)
            a2.set(title="Log-likelihood of the data", xlabel="EM iteration", ylabel="log-likelihood", xlim=(0, len(ll) - 1), ylim=(ll[0] - 30, ll[-1] + 30))
            a3.clear()
            a3.bar([0, 1, 2], h["R"][star], color=CAT[:3], width=0.6)
            a3.set(title="Responsibilities of the ★ customer", xlabel="component", ylabel="P(component | customer)", xticks=[0, 1, 2], ylim=(0, 1.0))
            caption(fig, f"iteration {i:>2}: log-likelihood {ll[i]:9.2f};  weights π = ({h['pi'][0]:.2f}, {h['pi'][1]:.2f}, {h['pi'][2]:.2f});  ★ customer: {h['R'][star][0]:.2f} / {h['R'][star][1]:.2f} / {h['R'][star][2]:.2f}")
            anim.grab(fig)


def selection_gif():
    X, z = shop_data()
    Ks = list(range(1, 8))
    fits = [best_of(X, K) for K in Ks]
    bic = [f.bic(X) for f in fits]; aic = [f.aic(X) for f in fits]; lls = [f.score(X) for f in fits]
    print("  K:    " + "  ".join(f"{K:7d}" for K in Ks)); print("  BIC:  " + "  ".join(f"{b:7.1f}" for b in bic)); print("  AIC:  " + "  ".join(f"{a:7.1f}" for a in aic))
    print(f"  best K by BIC = {Ks[int(np.argmin(bic))]}, by AIC = {Ks[int(np.argmin(aic))]} (true K = 3)")
    for ct in ("full", "diag", "spherical"):
        f = best_of(X, 3, ct)
        print(f"  covariance type {ct:9s}: parameters {f.n_params(2):4.0f}, log-likelihood {f.score(X):8.1f}, BIC {f.bic(X):8.1f}, accuracy {match_accuracy(z, f.predict(X), 3):.3f}")
    gx, gy, P = grid_for(X, res=100, pad=0.8)
    fig, (a1, a2, a3) = new_fig(1, 3, figsize=(13, 4.8), title="How many components? BIC trades fit against the number of parameters")
    fig.subplots_adjust(left=0.05, right=0.985, bottom=0.2, top=0.84, wspace=0.28)
    with Animator(here(__file__, "gmm_model_selection.gif"), fps=1.6, hold=3.5) as anim:
        for j, K in enumerate(Ks):
            f = fits[j]
            a1.clear()
            a1.scatter(X[:, 0], X[:, 1], s=14, c=blend(f.predict_proba(X), K) if K <= 8 else MUTED, edgecolor=INK, linewidth=0.2, zorder=3)
            draw_ellipses(a1, f.mu, f.cov, colors=CAT * 2)
            a1.set(title=f"K = {K} components", xlabel="average basket value", ylabel="visits per month", xlim=(-6, 5), ylim=(-3.5, 5))
            a2.clear()
            a2.plot(Ks[: j + 1], bic[: j + 1], "-o", color=BLUE, markersize=4, label="BIC"); a2.plot(Ks[: j + 1], aic[: j + 1], "-o", color=ORANGE, markersize=4, label="AIC")
            a2.axvline(3, color=MUTED, linestyle="--", linewidth=1); a2.text(3.08, max(bic) * 0.999, "true K", color=INK2, fontsize=8.5, va="top")
            a2.set(title="BIC / AIC (lower = better)", xlabel="number of components K", ylabel="criterion", xlim=(0.8, 7.2), ylim=(min(min(bic), min(aic)) - 30, max(max(bic), max(aic)) + 30)); a2.legend(loc="upper right")
            a3.clear()
            Rg = f.predict_proba(P)
            unc = 1 - Rg.max(1)
            a3.contourf(gx, gy, unc.reshape(gx.shape), levels=np.linspace(0, 0.6, 13), cmap="Blues", extend="max")
            a3.scatter(X[:, 0], X[:, 1], s=5, color=INK, alpha=0.5)
            a3.set(title="Uncertainty (dark = ambiguous)", xlabel="average basket value", ylabel="visits per month")
            caption(fig, f"K={K}: log-likelihood {lls[j]:.1f}, parameters {fits[j].n_params(2):.0f}, BIC {bic[j]:.1f}, AIC {aic[j]:.1f}   (more components always raise the likelihood; the criteria penalise the extra parameters)")
            anim.grab(fig)


def main():
    em_gif()
    selection_gif()
    try:
        from sklearn.mixture import GaussianMixture
        X, z = shop_data()
        mine = best_of(X, 3)
        sk = GaussianMixture(3, n_init=4, random_state=0, reg_covar=1e-6).fit(X)
        print(f"  [sklearn] avg log-likelihood per point: ours {mine.score(X) / len(X):.4f} vs sklearn {sk.score(X):.4f};  BIC ours {mine.bic(X):.1f} vs sklearn {sk.bic(X):.1f}")
    except ImportError:
        pass


if __name__ == "__main__":
    main()
